# Standard library
import uuid

# Third-party
from sqlalchemy import func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, ReferenceWithRankMixin


class CoreRefVisibility(Base, ReferenceWithRankMixin):
    __tablename__ = "core_ref_visibility"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        comment=(
            "Primary key UUID, auto-generated by the database. Uniquely "
            "identifies a visibility condition such as Clear, Partly Cloudy, "
            "Fog, or Whiteout."
        ),
    )
